import re
from typing import Dict


def parse_ini(text: str) -> Dict[str, Dict[str, str]]:
    def interpolate(value_part: str, current_section: str, sections: Dict[str, Dict]) -> str:
        visited = set()
        pattern = re.compile(r'\$\{([^}]+)\}')

        def replace(match: re.Match) -> str:
            content = match.group(1)
            parts = content.split(':', 1)

            # Check for cycles
            if len(parts) == 1:
                key = parts[0]
                if key in visited:
                    raise ValueError(f"Interpolation cycle detected: {visited} -> {key}")
                new_visited = visited.copy()
                new_visited.add(key)
            else:
                section_name, key = parts
                if section_name in visited:
                    raise ValueError(f"Interpolation cycle detected: {visited} -> {section_name}:{key}")
                new_visited = visited.copy()
                new_visited.add(section_name)

            # Resolve value
            if len(parts) == 1:
                # Key lookup in current section or DEFAULT
                val = sections[current_section].get(key)
                if val is None:
                    val = sections.get('DEFAULT', {}).get(key)
            else:
                # Section:key lookup
                section = sections.get(section_name)
                if section is None:
                    raise KeyError(f"Section '{section_name}' not found")
                val = section.get(key)
                if val is None:
                    val = sections.get('DEFAULT', {}).get(key)

            # Handle missing key/section
            if val is None:
                if len(parts) == 1:
                    if val is None:
                        raise KeyError(f"Key '{key}' not found in section '{current_section}' or DEFAULT")
                else:
                    if val is None:
                        raise KeyError(f"Key '{key}' not found in section '{section_name}' or DEFAULT")

            # Recursively resolve if string
            if isinstance(val, str):
                return replace(pattern, val)
            return str(val)

        return replace(pattern, value_part)

    sections = {'DEFAULT': {}}
    result = {}
    current_section = None
    prev_was_key = False
    last_key = None

    lines = [line.rstrip('\n') for line in text.splitlines()]

    for line in lines:
        stripped_line = line.strip()
        if not stripped_line or stripped_line.startswith(';') or stripped_line.startswith('#'):
            continue  # Rule 3: ignore empty/comments

        section_match = re.match(r'\s*\[([^\]]+)\s*\]', line)
        if section_match is not None:
            # Rule 1: process section header
            current_section = section_match.group(1)
            prev_was_key = False
            if current_section != 'DEFAULT' and current_section not in sections:
                sections[current_section] = {}
            continue

        if prev_was_key:
            if line.startswith(' '):
                # Rule 6: continuation line
                continuation_text = line.lstrip()
                current_section_dict = sections.get(current_section)
                if current_section_dict is None:
                    raise ValueError("Section not found (internal error)")
                current_section_dict[last_key] += '\n' + continuation_text
            else:
                raise ValueError(f"Malformed line (continuation without key)")
        else:
            # Rule 10: key line or malformed
            eq_pos = line.find('=')
            colon_pos = line.find(':')
            separator_pos = min(eq_pos, colon_pos) if eq_pos != -1 or colon_pos != -1 else -1

            if separator_pos == -1:
                raise ValueError("Malformed line: no separator found")

            key_part = line[:separator_pos].strip()
            value_part = line[separator_pos+1:].lstrip()  # Rule 2: value stripped

            if not key_part:
                raise ValueError("Malformed line: empty key")

            key = key_part.lower()  # Rule 2: key lowercased
            try:
                value = interpolate(value_part, current_section, sections)
            except (KeyError, ValueError) as e:
                raise ValueError(f"Line {text.splitlines().index(line) + 1}: {e}") from e

            if current_section == 'DEFAULT':
                sections['DEFAULT'][key] = value
            else:
                sections.setdefault(current_section, {})[key] = value

            last_key = key
            prev_was_key = True

    # Build result by merging sections with DEFAULT (Rule 8)
    for section_name in sections:
        if section_name == 'DEFAULT':
            continue
        merged = sections['DEFAULT'].copy()
        merged.update(sections[section_name])
        result[section_name] = merged

    return result
