class TTLCache:
    class Node:
        def __init__(self, key, value, expiry):
            self.key = key
            self.value = value
            self.expiry = expiry
            self.prev = None
            self.next = None

    def __init__(self, capacity: int, ttl: float, clock):
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self.cache = dict()
        self.head = None  # Most Recently Used
        self.tail = None  # Least Recently Used
        self.stats = {
            "hits": 0,
            "misses": 0,
            "evictions": 0,
            "expirations": 0,
        }

    def _remove_node(self, node):
        if node.prev:
            node.prev.next = node.next
        else:
            self.head = node.next
        if node.next:
            node.next.prev = node.prev
        else:
            self.tail = node.prev

    def _move_to_front(self, node):
        if node == self.head:
            return
        self._remove_node(node)
        node.next = self.head
        self.head.prev = node
        self.head = node
        if node.prev is None:
            self.tail = node

    def _add_to_front(self, key, value, expiry):
        new_node = self.Node(key, value, expiry)
        new_node.next = self.head
        if self.head:
            self.head.prev = new_node
        self.head = new_node
        if self.tail is None:
            self.tail = new_node

    def put(self, key, value):
        if self.capacity == 0:
            return
        now = self.clock()
        if key in self.cache:
            node = self.cache[key]
            node.value = value
            node.expiry = now + self.ttl
            self._move_to_front(node)
        else:
            expired = []
            current = self.head
            while current:
                next_node = current.next
                if current.expiry <= now:
                    expired.append(current)
                    self._remove_node(current)
                current = next_node
            self.stats["expirations"] += len(expired)
            current_size = len(self.cache)
            if current_size + 1 > self.capacity:
                if self.tail:
                    evicted_node = self.tail
                    self._remove_node(evicted_node)
                    del self.cache[evicted_node.key]
                    self.stats["evictions"] += 1
            self._add_to_front(key, value, now + self.ttl)

    def get(self, key, default=None):
        if self.capacity == 0:
            return default
        now = self.clock()
        if key not in self.cache:
            self.stats["misses"] += 1
            return default
        node = self.cache[key]
        if node.expiry <= now:
            self._remove_node(node)
            del self.cache[key]
            self.stats["expirations"] += 1
            self.stats["misses"] += 1
            return default
        self._move_to_front(node)
        self.stats["hits"] += 1
        return node.value

    def __len__(self):
        if self.capacity == 0:
            return 0
        now = self.clock()
        count = 0
        current = self.head
        while current:
            if current.expiry > now:
                count += 1
            current = current.next
        return count

    def stats(self):
        return {
            "hits": self.stats["hits"],
            "misses": self.stats["misses"],
            "evictions": self.stats["evictions"],
            "expirations": self.stats["expirations"],
        }
