def parse_duration(s: str) -> int:
    if not s.strip():
        raise ValueError("empty string")

    i = 0
    parts = []
    n = len(s)
    units_order = {'h', 'm', 's'}
    priorities = {'h': 0, 'm': 1, 's': 2}

    while i < n:
        # Skip leading whitespace
        while i < n and s[i].isspace():
            i += 1
        if i >= n:
            break  # Shouldn't occur due to initial check but handle defensively

        # Extract number part
        j = i
        while j < n and s[j].isdigit():
            j += 1
        if j == i:
            raise ValueError("number without unit")
        num = int(s[i:j])
        i = j

        # Skip whitespace after number
        while i < n and s[i].isspace():
            i += 1
        if i >= n:
            raise ValueError("number without unit")

        # Extract unit
        unit_char = s[i]
        unit = unit_char.lower()
        if unit not in units_order:
            raise ValueError("unknown unit")
        i += 1

        # Validate unit order and uniqueness
        if parts:
            prev_unit = parts[-1][1]
            prev_prio = priorities[prev_unit]
            curr_prio = priorities[unit]
            if curr_prio < prev_prio:
                raise ValueError("units out of order")
            if curr_prio == prev_prio:
                raise ValueError("repeated unit")

        parts.append((num, unit))

    # Calculate total seconds
    total = 0
    for num, unit in parts:
        if unit == 'h':
            total += num * 3600
        elif unit == 'm':
            total += num * 60
        else:
            total += num

    return total
