def summarize_ranges(nums: list[int]) -> str:
    sorted_unique = sorted(set(nums))
    if not sorted_unique:
        return ""

    groups = []
    current_group = [sorted_unique[0]]
    for num in sorted_unique[1:]:
        if num == current_group[-1] + 1:
            current_group.append(num)
        else:
            groups.append(current_group)
            current_group = [num]
    groups.append(current_group)

    result = []
    for group in groups:
        if len(group) >= 3:
            result.append(f"{group[0]}..{group[-1]}")
        else:
            result.extend(map(str, group))

    return ",".join(result)
